#!/usr/bin/env python3
"""Bundles scripts/worker_parts/*.js into app/src/main/assets/web/studio-engine.js."""
import glob
import os

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
PARTS_DIR = os.path.join(ROOT, "scripts", "worker_parts")
OUT_FILE = os.path.join(ROOT, "app", "src", "main", "assets", "web", "studio-engine.js")


def main() -> None:
    part_paths = sorted(glob.glob(os.path.join(PARTS_DIR, "*.js")))
    if not part_paths:
        raise SystemExit(f"No worker parts found in {PARTS_DIR}")

    chunks = [
        "/* AUTO-GENERATED by scripts/build_studio_engine.py — DO NOT EDIT DIRECTLY */\n",
        "(function () {\n",
        "'use strict';\n",
    ]
    for path in part_paths:
        rel = os.path.relpath(path, ROOT)
        with open(path, "r", encoding="utf-8") as fh:
            body = fh.read()
        chunks.append(f"\n// ===== {rel} =====\n")
        chunks.append(body)
        if not body.endswith("\n"):
            chunks.append("\n")

    chunks.append("\n})();\n")

    os.makedirs(os.path.dirname(OUT_FILE), exist_ok=True)
    with open(OUT_FILE, "w", encoding="utf-8", newline="\n") as out:
        out.write("".join(chunks))

    size_kb = os.path.getsize(OUT_FILE) / 1024.0
    print(f"Built {os.path.relpath(OUT_FILE, ROOT)} from {len(part_paths)} parts ({size_kb:.1f} KB)")


if __name__ == "__main__":
    main()
